write('tests/growth-request-arbiter.test.mjs', `import assert from 'node:assert/strict';\nimport { GROWTH_REQUEST, decideGrowthRequest, growthRequestDecision, writerStateFromLength, createGrowthRequestArbiter } from '../js/growth-request-arbiter.mjs';\n\nconst base = { ready: true, writerState: 'E0', accountState: 'signed-out', signedIn: false, safelySaved: false, localProtected: false, meaningfulOutcome: false, communityEligible: false, keepEnabled: true, shareEnabled: true, communityEnabled: true };\nconst winner = (patch) => decideGrowthRequest({ ...base, ...patch });\n\nassert.equal(writerStateFromLength(0), 'E0');\nassert.equal(writerStateFromLength(50), 'E1');\nassert.equal(writerStateFromLength(250), 'E2');\nassert.equal(writerStateFromLength(700), 'E3');\nassert.equal(writerStateFromLength(1200), 'E4');\nassert.equal(writerStateFromLength(20, true), 'E5');\nassert.equal(writerStateFromLength(0, true), 'E0', 'empty writing must never become E5');\n\nassert.equal(winner({ writerState: 'E0' }), GROWTH_REQUEST.NONE);\nassert.equal(winner({ writerState: 'E2' }), GROWTH_REQUEST.NONE);\nassert.equal(winner({ writerState: 'E3' }), GROWTH_REQUEST.KEEP, 'substantial unsaved work must protect recovery first');\nassert.equal(winner({ writerState: 'E4', accountState: 'signed-in', signedIn: true, safelySaved: true, communityEligible: true }), GROWTH_REQUEST.COMMUNITY_PUBLISH, 'saved signed-in long form can promote Community Publish');\nassert.equal(winner({ writerState: 'E5', meaningfulOutcome: true, localProtected: false, communityEligible: true }), GROWTH_REQUEST.KEEP, 'unprotected completed work keeps recovery priority');\nassert.equal(winner({ writerState: 'E5', meaningfulOutcome: true, localProtected: true, communityEligible: true }), GROWTH_REQUEST.SHARE, 'safely retained completed work promotes Share before Community Publish');\nassert.equal(winner({ writerState: 'E4', keepEnabled: false, communityEligible: false }), GROWTH_REQUEST.NONE, 'Voice Keep can stay disabled until Slice 3');\n\nconst multi = growthRequestDecision({ ...base, writerState: 'E5', meaningfulOutcome: true, localProtected: true, safelySaved: true, communityEligible: true, signedIn: true, accountState: 'signed-in' });\nassert.equal(multi.winner, GROWTH_REQUEST.SHARE);\nassert.deepEqual(multi.suppressed, [GROWTH_REQUEST.COMMUNITY_PUBLISH]);\n\nconst events = [];\nconst arbiter = createGrowthRequestArbiter({ workspace: 'rich-editor', telemetry: (name, detail) => events.push({ name, detail }) });\narbiter.update({ ...base, ready: true, writerState: 'E5', signedIn: true, accountState: 'signed-in', safelySaved: true, localProtected: true, meaningfulOutcome: true, communityEligible: true });\nassert.equal(arbiter.current(), GROWTH_REQUEST.SHARE);\nassert.ok(events.some((event) => event.detail.growth_stage === 'suppressed_due_to_arbitration' && event.detail.request_family === 'community_publish' && event.detail.suppression_winner === 'share'));\nassert.ok(events.every((event) => !('text' in event.detail) && !('content' in event.detail)), 'arbiter telemetry must be bounded state only');\nconsole.log('Growth request arbiter decision matrix passed.');\n`);

write('tests/product-pulse-slice2-contract.test.js', `const assert = require('node:assert');\nconst fs = require('node:fs');\nconst path = require('node:path');\nconst root = path.resolve(__dirname, '..');\nconst read = (file) => fs.readFileSync(path.join(root, file), 'utf8');\n\nconst growth = read('js/growth-request-arbiter.mjs');\nconst account = read('js/account-growth-entry.mjs');\nconst community = read('js/community-publishing-ui.mjs');\nconst telemetry = read('js/product-telemetry.js');\nconst events = read('functions/api/events.js');\nconst pulse = read('functions/api/internal/product-pulse.js');\nconst html = read('os/product-pulse.html');\nconst client = read('js/product-pulse.js');\nconst migration = read('migrations/0020_growth_request_arbiter.sql');\n\nassert.match(growth, /return growthRequestDecision\(input\)\.winner/, 'public arbiter decision must return one enum winner');\nassert.match(growth, /if \(keep\) winner = GROWTH_REQUEST\.KEEP[\\s\\S]*else if \(share\)[\\s\\S]*else if \(community\)/, 'priority must be Keep → Share → Community Publish');\nassert.match(account, /WriteUrduGrowthRequestArbiter = growthArbiter/, 'account-growth entry must be the one runtime owner');\nassert.match(account, /keepEnabled: path !== '\/tools\/urdu-voice-typing'/, 'Slice 2 must not pre-empt the Slice 3 Voice Keep experiment');\nassert.match(account, /Create free account to keep this writing/, 'signed-out Keep may use acquisition copy');\nassert.match(account, /signedIn \? 'Save this writing in My Documents/, 'signed-in Keep copy must not ask the user to create an account');\nassert.match(community, /owner\.current\(\) === 'community_publish'/, 'Community promotion must render only when it wins arbitration');\nassert.match(community, /toolbarButton\.hidden = !wins \|\| promptEligible/, 'Community must expose only one promoted control at a time');\nassert.match(community, /owner\.update\(\{ communityEligible: familyEligible \}\)/, 'Community must pass only bounded eligibility into the shared owner');\nassert.match(telemetry, /request_family: detail\.request_family/, 'client telemetry must carry bounded family');\nassert.match(telemetry, /growth_stage: detail\.growth_stage/, 'client telemetry must carry bounded stage');\nassert.match(events, /GROWTH_REQUEST_FAMILIES = new Set/, 'server must bound growth request families');\nassert.match(events, /GROWTH_STAGES = new Set/, 'server must bound growth stages');\nassert.match(events, /growth_hourly_requests/, 'Slice 2 must use aggregate same-D1 rollups');\nassert.doesNotMatch(events, /INSERT(?: OR IGNORE)? INTO product_events/i, 'Slice 2 must not restore raw event writes');\nassert.doesNotMatch(migration, /^\\s*(text|content|transcript|audio|filename|document_id|share_id|email|account_id)\\s+/im, 'growth rollup must not declare content or identity columns');\nassert.match(pulse, /function growthRequestSection\(/, 'Product Pulse must expose growth arbitration diagnostics');\nassert.match(pulse, /growth_hourly_requests/, 'Product Pulse must read aggregate growth rollups');\nassert.match(html, /id="growthRequestPanel"/, 'Founder dashboard must render Slice 2 panel');\nassert.match(client, /function renderGrowthRequests\(/, 'dashboard client must render growth request diagnostics');\nconsole.log('Product Pulse Slice 2 growth-arbiter contracts passed.');\n`);

